private bool IsChamBaiThiMethodTest(DataRow drw)
{
    if (drw == null)
        return false;

    if (drw.Table.Columns.Contains("MethodTestCode")
        && drw["MethodTestCode"] != DBNull.Value
        && drw["MethodTestCode"].ToString().Trim() != "")
    {
        return string.Equals(drw["MethodTestCode"].ToString().Trim(), "CB", StringComparison.OrdinalIgnoreCase);
    }

    if (!drw.Table.Columns.Contains("MethodTestID")
        || drw["MethodTestID"] == DBNull.Value
        || drw["MethodTestID"].ToString().Trim() == "")
        return false;

    int intMethodTestID = Convert.ToInt32(drw["MethodTestID"]);
    BO.SIM_MethodTest itemMethodTest = new SIM_MethodTestDAO().Get(intMethodTestID);
    if (itemMethodTest == null
        || itemMethodTest.MethodTestCode == null
        || itemMethodTest.MethodTestCode.Trim() == "")
        return false;

    return string.Equals(itemMethodTest.MethodTestCode.Trim(), "CB", StringComparison.OrdinalIgnoreCase);
}

